<script setup>
import {computed,ref} from 'vue';
import {cabinetCompartments} from '../shared/cabinet-compartments.mjs';
const props=defineProps({item:{type:Object,required:true}});
import {cabinetParts} from '../shared/cabinet-parts.mjs';
const showFronts=ref(false);
const fronts=computed(()=>cabinetParts(props.item).filter(part=>part.part.startsWith('front')));
const layout=computed(()=>cabinetCompartments(props.item));
</script>
<template><section aria-label="Applied cabinet compartments"><h3>Applied compartments</h3><p data-testid="cabinet-compartment-summary">{{ layout.columns }} columns · {{ item.columnShelves ? 'shelves '+layout.bays.map(b=>b.shelves).join(' / ') : item.shelves+' shelves per column' }} · {{ layout.bays.reduce((sum,b)=>sum+b.shelves+1,0) }} compartments</p><p class="hint">Clear bay widths (mm): {{ layout.bays.map(b=>(b.width*1000).toFixed(1)).join(' / ') }}. Cabinet shelves sets the default count; independent counts override it. Diagram shows applied geometry. Toggle fronts to inspect the closed-door layout. Apply cabinet to update.</p><p v-if="item.columnFronts" data-testid="cabinet-front-summary">Fronts: {{ item.columnFronts.join(' / ') }}</p><label class="snap-toggle"><input v-model="showFronts" type="checkbox" aria-label="Show fronts in cabinet elevation">Show fronts in cabinet elevation</label><svg role="img" aria-label="Cabinet compartment elevation" :viewBox="`${-item.width/2} 0 ${item.width} ${item.height}`" style="width:100%;height:180px;background:#e9eee7"><rect :x="-item.width/2" y="0" :width="item.width" :height="item.height" fill="#b88c59"/><rect v-for="(bay,i) in layout.bays" :key="i" :x="bay.x-bay.width/2" :y="item.thickness" :width="bay.width" :height="item.height-2*item.thickness" fill="#f4f1e9"/><g v-for="(bay,i) in layout.bays" :key="'s'+i"><rect v-for="n in bay.shelves" :key="n" :x="bay.x-bay.width/2" :y="item.height-(item.thickness+(item.height-2*item.thickness)*n/(bay.shelves+1))-item.thickness/2" :width="bay.width" :height="item.thickness" fill="#b88c59"/></g><g v-if="showFronts"><rect v-for="(front,i) in fronts" :key="i" data-front-panel="true" :x="front.position[0]-front.size[0]/2" :y="item.height-front.position[1]-front.size[1]/2" :width="front.size[0]" :height="front.size[1]" fill="#cfad76" stroke="#5f4c2f" :stroke-width="item.thickness/6"/></g></svg></section></template>
